CREATE SCHEMA IF NOT EXISTS app;
CREATE TABLE IF NOT EXISTS app."User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"name" TEXT,"passwordHash" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'active',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE IF NOT EXISTS app."Role" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS app."Permission" ("id" TEXT PRIMARY KEY,"key" TEXT NOT NULL UNIQUE,"description" TEXT);
CREATE TABLE IF NOT EXISTS app."UserRole" ("userId" TEXT NOT NULL,"roleId" TEXT NOT NULL,PRIMARY KEY("userId","roleId"),FOREIGN KEY("userId") REFERENCES app."User"("id") ON DELETE CASCADE,FOREIGN KEY("roleId") REFERENCES app."Role"("id") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS app."RolePermission" ("roleId" TEXT NOT NULL,"permissionId" TEXT NOT NULL,PRIMARY KEY("roleId","permissionId"),FOREIGN KEY("roleId") REFERENCES app."Role"("id") ON DELETE CASCADE,FOREIGN KEY("permissionId") REFERENCES app."Permission"("id") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS app."WaitlistEntry" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL UNIQUE,"phone" TEXT NOT NULL,"state" TEXT NOT NULL,"city" TEXT NOT NULL,"institution" TEXT NOT NULL,"marketingConsent" BOOLEAN NOT NULL DEFAULT false,"source" TEXT NOT NULL DEFAULT 'dino-website',"status" TEXT NOT NULL DEFAULT 'new',"internalNotes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX IF NOT EXISTS "WaitlistEntry_status_createdAt_idx" ON app."WaitlistEntry"("status","createdAt");
CREATE TABLE IF NOT EXISTS app."Contact" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"phone" TEXT,"topic" TEXT NOT NULL,"message" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'new',"internalNotes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX IF NOT EXISTS "Contact_status_createdAt_idx" ON app."Contact"("status","createdAt"); CREATE INDEX IF NOT EXISTS "Contact_email_idx" ON app."Contact"("email");
CREATE TABLE IF NOT EXISTS app."BlogPost" ("id" TEXT PRIMARY KEY,"slug" TEXT NOT NULL UNIQUE,"title" TEXT NOT NULL,"excerpt" TEXT,"body" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'draft',"publishedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE IF NOT EXISTS app."Job" ("id" TEXT PRIMARY KEY,"slug" TEXT NOT NULL UNIQUE,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'draft',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE IF NOT EXISTS app."Application" ("id" TEXT PRIMARY KEY,"jobId" TEXT NOT NULL,"email" TEXT NOT NULL,"name" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'received',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("jobId") REFERENCES app."Job"("id"));
CREATE TABLE IF NOT EXISTS app."AuditLog" ("id" TEXT PRIMARY KEY,"actorUserId" TEXT,"action" TEXT NOT NULL,"resourceType" TEXT NOT NULL,"resourceId" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "AuditLog_createdAt_idx" ON app."AuditLog"("createdAt");
